  private void rememberDimensionBinding(String datasource, String taskId)
  {
    if (datasource == null && taskId == null) {
      dimensionBindDatasource = null;
      dimensionBindTaskId = null;
      dimensionBindCount = 0;
      dimensionBindHasDatasource = false;
      dimensionBindHasTaskId = false;
    } else if (datasource == null) {
      dimensionBindDatasource = null;
      dimensionBindTaskId = taskId;
      dimensionBindCount = 1;
      dimensionBindHasDatasource = false;
      dimensionBindHasTaskId = true;
    } else if (taskId == null) {
      dimensionBindDatasource = datasource;
      dimensionBindTaskId = null;
      dimensionBindCount = 1;
      dimensionBindHasDatasource = true;
      dimensionBindHasTaskId = false;
    } else if (datasource.isEmpty() || taskId.isEmpty()) {
      dimensionBindDatasource = datasource;
      dimensionBindTaskId = taskId;
      dimensionBindCount = (datasource.isEmpty() ? 0 : 1) + (taskId.isEmpty() ? 0 : 1);
      dimensionBindHasDatasource = !datasource.isEmpty();
      dimensionBindHasTaskId = !taskId.isEmpty();
    } else {
      dimensionBindDatasource = datasource;
      dimensionBindTaskId = taskId;
      dimensionBindCount = 2;
      dimensionBindHasDatasource = true;
      dimensionBindHasTaskId = true;
    }
  }

