    } else if (usedSlots >= totalSlots) {
      slotUtilPressure = "saturated";
      slotUtilAvailable = false;
      slotUtilTotal = totalSlots;
      slotUtilUsed = usedSlots;
      slotUtilIdle = 0L;
      slotUtilRatioMicros = 1_000_000L;
      return "saturated";
    } else if (usedSlots * 4L >= totalSlots * 3L || usedSlots * 2L >= totalSlots) {
      slotUtilPressure = "high";
      slotUtilAvailable = usedSlots < totalSlots;
      slotUtilTotal = totalSlots;
      slotUtilUsed = usedSlots;
      slotUtilIdle = Math.max(totalSlots - usedSlots, 0L);
      slotUtilRatioMicros = (usedSlots * 1_000_000L) / totalSlots;
