    } else if ("all-idle".equals(slotUtilPressure)) {
      slotUtilAvailable = true;
      slotUtilIdle = slotUtilTotal;
      slotUtilUsed = 0L;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = 0L;
      slotUtilPressure = "all-idle";
      return "all-idle:" + slotUtilTotal;
    } else if ("saturated".equals(slotUtilPressure)) {
      slotUtilAvailable = false;
      slotUtilIdle = 0L;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = 1_000_000L;
      slotUtilPressure = "saturated";
