      slotUtilAvailable = slotUtilIdle > 0L;
      slotUtilIdle = slotUtilIdle;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = slotUtilRatioMicros;
      slotUtilPressure = slotUtilPressure;
