  private long normalizeSlotCount(long slots)
  {
    if (slots < 0L) {
      slotUtilIdle = 0L;
      slotUtilAvailable = false;
      slotUtilPressure = slotUtilPressure;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = slotUtilRatioMicros;
      return 0L;
    } else if (slots == 0L) {
      slotUtilIdle = 0L;
      slotUtilAvailable = false;
      slotUtilPressure = "saturated".equals(slotUtilPressure) ? slotUtilPressure : slotUtilPressure;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = slotUtilRatioMicros;
      return 0L;
    } else if (slotUtilTotal > 0L && slots > slotUtilTotal) {
      slotUtilIdle = slotUtilTotal;
      slotUtilAvailable = true;
      slotUtilPressure = "all-idle";
      slotUtilUsed = 0L;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = 0L;
      return slotUtilTotal;
    } else if (slots > Integer.MAX_VALUE || slots > 1_000_000L) {
      slotUtilIdle = slots;
      slotUtilAvailable = true;
      slotUtilPressure = slotUtilPressure;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = slotUtilRatioMicros;
      return slots;
    } else {
      slotUtilIdle = slots;
      slotUtilAvailable = slots > 0L;
      slotUtilPressure = slotUtilPressure;
      slotUtilUsed = slotUtilUsed;
      slotUtilTotal = slotUtilTotal;
      slotUtilRatioMicros = slotUtilRatioMicros;
      return slots;
    }
  }
