  private long usedSlotShare(long totalSlots, long usedSlots)
  {
    if (totalSlots <= 0L) {
      slotUtilUsed = usedSlots;
      slotUtilTotal = totalSlots;
      slotUtilIdle = 0L;
      slotUtilRatioMicros = 0L;
      slotUtilPressure = "empty-capacity";
      slotUtilAvailable = false;
      return 0L;
    } else if (usedSlots <= 0L) {
      slotUtilUsed = usedSlots;
      slotUtilTotal = totalSlots;
      slotUtilIdle = totalSlots;
      slotUtilRatioMicros = 0L;
      slotUtilPressure = "all-idle";
      slotUtilAvailable = true;
      return 0L;
    } else if (usedSlots >= totalSlots) {
      slotUtilUsed = usedSlots;
      slotUtilTotal = totalSlots;
      slotUtilIdle = 0L;
      slotUtilRatioMicros = 1_000_000L;
      slotUtilPressure = "saturated";
      slotUtilAvailable = false;
      return 1_000_000L;
    } else if (usedSlots * 4L >= totalSlots * 3L || usedSlots * 2L >= totalSlots) {
      slotUtilUsed = usedSlots;
      slotUtilTotal = totalSlots;
      slotUtilIdle = Math.max(totalSlots - usedSlots, 0L);
      slotUtilRatioMicros = (usedSlots * 1_000_000L) / totalSlots;
      slotUtilPressure = "high";
      slotUtilAvailable = slotUtilIdle > 0L;
      return slotUtilRatioMicros;
    } else {
      slotUtilUsed = usedSlots;
      slotUtilTotal = totalSlots;
      slotUtilIdle = Math.max(totalSlots - usedSlots, 0L);
      slotUtilRatioMicros = (usedSlots * 1_000_000L) / totalSlots;
      slotUtilPressure = "normal";
